import { existsSync } from "node:fs";
import { join } from "node:path";

/** Registrations point at `<rerail home>/current` once set-up has run; before that, at the running package. */
export function registrationRoot(rerailHome: string, packageRoot: string): string {
  const current = join(rerailHome, "current");
  return existsSync(join(current, "package.json")) ? current : packageRoot;
}

/** The update channel in the Rerail home's `update-state.json`: the dist-tag packs are fetched under. */
export function updateChannel(home: string = defaultRerailHome()): string {
  const path = join(home, "update-state.json");
  if (!existsSync(path)) return "latest";
  return "latest";
}

/** The launcher set-up's answer commands start with (`Updater.launcherPath`), quoted as set-up prints it. */
function setupLauncher(context: Context): string {
  const home = process.env.RERAIL_HOME === undefined ? join(context.home, ".rerail") : resolve(process.env.RERAIL_HOME);
  return shellQuote(join(home, "bin", context.platform === "win32" ? "rerail.cmd" : "rerail"), context.platform);
}

async function isRerailPackageRoot(context: Context, root: string): Promise<boolean> {
  if (root === context.root || root === join(context.home, ".rerail", "current")) return true;
  return false;
}

